'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',projects:'M3 7h7l2 2h9v11H3zM3 7V4h7l2 3',milestones:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',attention:'M12 3 2 21h20zM12 9v5m0 3h.01',sources:'M8 8 4 12l4 4m8-8 4 4-4 4M14 4l-4 16',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',refresh:'M21 8a9 9 0 0 0-16-3L2 8m0-6v6h6m-5 8a9 9 0 0 0 16 3l3-3m0 6v-6h-6',moon:'M20 14a8 8 0 0 1-10-10 9 9 0 1 0 10 10',arrow:'M5 12h14m-6-6 6 6-6 6',external:'M14 3h7v7m0-7L10 14M10 3H4v17h17v-7',pin:'M8 3h8l-1 6 4 4H5l4-4zM12 13v8',back:'M19 12H5m6-6-6 6 6 6',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',circle:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 5v4m0 4h.01'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.circle}"/></svg>`;}
function wireIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
wireIcons();
const local=document.documentElement.dataset.mode!=='snapshot'&&['127.0.0.1','localhost'].includes(location.hostname);
const titles={live:'Live · Không gian vận hành',overview:'Tổng quan',projects:'Dự án của bạn',milestones:'Mốc công việc',attention:'Những việc cần chú ý',sources:'Nguồn kết nối',tools:'Công cụ thị trường',missions:'Mission của 8 module',connections:'Liên kết 7 module'};
const stateLabels={PENDING:'Chờ nghiệm thu',APPLIED:'Đã áp dụng',SCOPED_QC:'QC trong phạm vi',PLANNING:'Kế hoạch',NOT_RUN:'Chưa chạy',IN_PROGRESS:'Đang hoàn thiện',NOT_STARTED:'Chưa bắt đầu',BLOCKED:'Đang bị chặn',ACCEPTED_SCOPED:'Nhận trong phạm vi',BOOTSTRAP_FAILED_PHASE1_NOT_QUALIFIED:'Chưa qualification',NOT_EXECUTED:'Chưa thực thi',BLOCKED_PENDING_OWNER_DECISION_EXECUTION_AND_QC:'Chờ quyết định và QC'};
let portfolio=null,busy=false,projectFilter='',milestoneProject='all',milestoneState='all',onlyPinned=false;
let pins=[];try{pins=JSON.parse(localStorage.getItem('fitechhub-pins')||'[]');if(!Array.isArray(pins))pins=[];}catch{}
function date(value,time=true){if(!value)return'Chưa ghi nhận';return new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',...(time?{hour:'2-digit',minute:'2-digit'}:{year:'numeric'})}).format(new Date(value));}
function project(id){return portfolio?.projects.find(p=>p.id===id);}
function badge(text,tone='neutral'){return `<span class="badge ${esc(tone)}">${esc(text)}</span>`;}
function milestoneTone(state){return /BLOCK|FAILED|PENDING/.test(state)?'amber':/ACCEPT|SCOPED|APPLIED/.test(state)?'teal':'neutral';}
function stageClass(state){return /BLOCK|FAILED/.test(state)?'blocked':/ACCEPT|SCOPED|APPLIED/.test(state)?'scoped':/IN_PROGRESS|PENDING/.test(state)?'started':'';}
function projectMark(p){return `<div class="project-mark ${esc(p.color)}">${p.id==='fitechml'?icon('sources'):p.id==='fitechsnm'?`<span class="snm-monogram">${esc(p.mark)}<small>↗</small></span>`:esc(p.mark)}</div>`;}
function openUrl(p,route){if(local)return `http://127.0.0.1:${p.port}/${route||p.local_route}`;if(!p.public_url)return null;const u=new URL(p.public_url,document.baseURI);if(route){if(route.startsWith('#'))u.hash=route;else return new URL(route,u).href;}return u.href;}
function externalButton(p,text,route,cls='secondary'){const url=openUrl(p,route);return url?`<a class="button ${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)}${icon('external')}</a>`:`<button class="button secondary" disabled title="Dashboard con chưa có bản công khai">Chưa có bản công khai</button>`;}
function dashboardAction(p){const url=openUrl(p);return `<div class="dashboard-action">${url?`<a class="button dashboard-open" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="Mở dashboard ${esc(p.name)}">Mở dashboard${icon('external')}</a>`:`<button class="button dashboard-open" disabled aria-label="Mở dashboard ${esc(p.name)} — chưa có bản online">Mở dashboard${icon('external')}</button>`}<span class="dashboard-availability">${url?(local?'Mở bản gốc trên máy này':'Mở bản snapshot trên Internet'):'Chưa có bản online · chỉ xem được tóm tắt'}</span></div>`;}
function card(p){const ms=p.milestones,tracked=pins.includes(p.id);return `<article class="project-card ${esc(p.color)}" data-project-card="${esc(p.id)}"><div class="card-top">${projectMark(p)}<div class="card-title"><h3><a href="#project/${esc(p.id)}">${esc(p.name)} <small>${esc(p.suffix)}</small></a></h3><p>${esc(p.category)}</p></div><button class="pin ${tracked?'pinned':''}" data-pin="${esc(p.id)}" aria-label="${tracked?'Bỏ ghim':'Ghim'} ${esc(p.name)}" aria-pressed="${tracked}">${icon('pin')}</button></div><p class="card-description">${esc(p.description)}</p>${missionTeaser(p.id)}<div class="phase-line"><strong><span class="phase-pill">${esc(p.phase)}</span>${esc(p.phase_title)}</strong>${badge(p.status_label,p.status_tone)}</div><div class="milestone-track" aria-label="Trạng thái các mốc; không biểu thị phần trăm hoàn thành">${(ms.length?ms:[{state:'UNKNOWN'}]).map(m=>`<span class="milestone-step ${stageClass(m.state)}" title="${esc(m.id||'Chưa có milestone API')}: ${esc(m.state)}"></span>`).join('')}</div><p class="track-note">${ms.length?`${ms.length} mốc đã ghi nhận · trạng thái theo từng nguồn`:(p.group==='tools'?'Snapshot công cụ · không phải mốc nghiên cứu':'Readiness kỹ thuật · chưa xác nhận mốc khoa học')}</p><div class="card-facts">${(p.facts.length?p.facts:[{label:'Nguồn',value:'Chưa kết nối'},{label:'Trạng thái',value:'Chưa xác minh'}]).slice(0,2).map(f=>`<div><span>${esc(f.label)}</span><strong>${esc(f.value)}</strong></div>`).join('')}</div>${dashboardAction(p)}<div class="card-footer"><span class="source-health"><i class="live-dot ${p.connected?'':'offline'}"></i>${p.connected?(local?'Đã đọc nguồn local':'Snapshot đã ghi nhận'):'Nguồn chưa kết nối'}</span><a class="open-project" href="#project/${esc(p.id)}">Xem tóm tắt${icon('arrow')}</a></div></article>`;}
function orbitNode(p,x,y){return `<a href="#project/${esc(p.id)}" aria-label="Xem ${esc(p.name)}"><rect class="node-plate" x="${x-22}" y="${y-22}" width="44" height="44" rx="14"/><text class="node-initial" x="${x}" y="${y+5}" text-anchor="middle">${esc(p.mark)}</text><text class="node-label" x="${x}" y="${y+37}" text-anchor="middle">${esc(p.name)}</text></a>`;}
function orbit(group,title){const items=portfolio.projects.filter(p=>(p.group||'research')===group);const xy=group==='tools'?[[140,44],[62,179],[218,179]]:[[76,68],[204,68],[76,196],[204,196]];const center=group==='tools'?`<text class="market-orbit-initial" x="140" y="143" text-anchor="middle" fill="#4056cb" font-family="inherit" font-size="30" font-weight="800">M</text>`:`<text class="research-orbit-initial" x="140" y="143" text-anchor="middle" fill="#4056cb" font-family="inherit" font-size="30" font-weight="800">${esc(project('fitechsnm')?.mark||'N')}</text><text x="156" y="122" text-anchor="middle" fill="#4056cb" font-size="10">↗</text>`;return `<figure class="workspace-orbit ${group}"><svg viewBox="0 0 280 246" role="group" aria-label="${esc(title)}"><circle class="orbit-outline" cx="140" cy="132" r="90"/><circle class="orbit-ring" cx="140" cy="132" r="63"/>${items.map((p,i)=>{const [x,y]=xy[i];return `<path class="flowline" d="M140 132L${x} ${y}"/>`+orbitNode(p,x,y);}).join('')}<rect class="node-center" x="118" y="110" width="44" height="44" rx="14"/>${center}<circle cx="159" cy="112" r="4.5" fill="#a4e5d8"/></svg><figcaption>${title}<span>${items.length} ${group==='tools'?'công cụ':'dự án'}</span></figcaption></figure>`;}
function constellation(){const q=project('qrw');return `<div class="orbit-pair foundation-map">${orbit('research','Dự án nghiên cứu')}<a class="foundation-node" href="#project/qrw" aria-label="Xem nền tảng QRW"><span class="foundation-symbol">${esc(q.mark)}</span><strong>QRW</strong><span>Quản trị dữ liệu</span><small>Nền tảng chung</small><em>${q?.connected?'V2 đang triển khai':'Nguồn chưa kết nối'}</em></a>${orbit('tools','Công cụ thị trường')}</div>`;}
function foundationFeature(){const q=filteredProjects().find(p=>p.id==='qrw');if(!q)return '';return `<section class="foundation-feature" aria-label="Nền tảng dữ liệu QRW"><div class="foundation-feature-title"><span class="foundation-symbol">${esc(q.mark)}</span><div><p>Nền tảng cho 7 module</p><h2>QRW <small>Data Foundation</small></h2><p>Nguồn · Hợp đồng · Phiên bản · Lineage</p></div></div><div class="foundation-facts">${q.facts.map(f=>`<div><span>${esc(f.label)}</span><strong>${esc(f.value)}</strong></div>`).join('')}</div><div class="foundation-feature-actions"><a class="text-link" href="#mission/qrw">Mission nền tảng${icon('arrow')}</a>${externalButton(q,'Mở dashboard QRW',null,'dashboard-open')}<a class="text-link" href="#project/qrw">Xem tiến độ nền tảng${icon('arrow')}</a></div>${missionTeaser('qrw')}<p class="foundation-state">${esc(q.next_action)} · Tích hợp này chỉ theo dõi monitor, chưa đổi nguồn dữ liệu của module.</p></section>`;}
function attentionItems(limit=99){return portfolio.projects.flatMap(p=>p.attention.map(a=>({...a,p}))).slice(0,limit).map(a=>`<div class="attention-item ${a.p.color}"><span class="attention-marker">${esc(a.p.mark)}</span><div class="attention-copy"><h3><a href="#project/${esc(a.p.id)}">${esc(a.title)}</a></h3><p>${esc(a.detail)}</p><small>${esc(a.p.name)}</small></div><a href="#project/${esc(a.p.id)}" aria-label="Xem ${esc(a.p.name)}">${icon('arrow')}</a></div>`).join('');}
function overview(){const count=portfolio.projects.reduce((n,p)=>n+p.milestones.length,0),published=portfolio.projects.filter(p=>p.public_url).length;return `<a class="live-entry" href="#live"><div><strong>Không gian đang vận hành</strong><small>Bản đồ Live · Tiến trình · Sự kiện</small></div><span>↗</span></a><div class="hero-grid"><section class="hero"><div class="hero-copy"><p class="hero-greeting"><span></span>Chào Sơn, mọi dự án ở đây.</p><h2>${portfolio.projects.filter(p=>p.group!=='foundation').length} module.<br>Một nền dữ liệu.</h2><p>QRW ở lớp nền chung, kết nối không gian nghiên cứu và công cụ thị trường.</p><div class="hero-buttons"><a href="#projects" class="button white">Khám phá workspace${icon('arrow')}</a><a href="#milestones" class="button darkglass">Xem các mốc</a></div></div>${constellation()}</section><aside class="status-panel"><div class="panel-eyeline"><h3>Không gian nghiên cứu</h3><span class="small-icon">${icon('projects')}</span></div><div class="status-row"><span>Dashboard kết nối</span><strong>${String(portfolio.total).padStart(2,'0')}</strong></div><div class="status-row"><span>${local?'Nguồn metadata phản hồi':'Nguồn có trong snapshot'}</span><strong>${portfolio.connected} / ${portfolio.total}</strong></div><div class="status-row"><span>Mốc đã ghi nhận</span><strong>${count}</strong></div><div class="status-panel-foot">${icon('shield')}Chỉ theo dõi · không thực thi</div></aside></div>${foundationFeature()}<section class="mission-entry-banner"><div><h2>Tám mission. Bảy vai trò bổ sung nhau.</h2><p>Mục tiêu, phương pháp và đầu ra của từng module — giữ rõ kết quả đã có và đích còn phải kiểm chứng.</p></div><a class="button secondary" href="#missions">Khám phá mission${icon('arrow')}</a><a class="text-link" href="#connections">Liên kết 7 module${icon('arrow')}</a></section><div class="section-heading"><div><h2>Workspace của bạn<small>${portfolio.projects.filter(p=>p.group!=='foundation').length}</small></h2><p>Bốn dự án nghiên cứu và ba công cụ thị trường, trên nền tảng QRW.</p></div><div class="tabs" aria-label="Lọc workspace"><button data-pins-filter="all" class="${!onlyPinned?'selected':''}">Tất cả</button><button data-pins-filter="pinned" class="${onlyPinned?'selected':''}">Đã ghim</button></div></div>${groupedCards()}<div class="lower-grid"><section class="paper-panel"><div class="section-heading"><div><h2>Cần chú ý</h2><p>Giữ rõ việc tiếp theo của từng dự án.</p></div><a class="text-link" href="#attention">Xem tất cả${icon('arrow')}</a></div>${attentionItems(8)}</section><section class="paper-panel"><div class="section-heading"><div><h2>Lần đọc gần nhất</h2><p>Quan sát nguồn, không phải nhật ký chạy job.</p></div>${icon('clock')}</div><ol class="updates">${portfolio.projects.map(p=>`<li class="${p.color}"><strong>${esc(p.name)}</strong><span>${esc(p.phase)} · ${esc(p.status_label)}</span><time>${date(p.checked_at)}</time></li>`).join('')}</ol></section></div>`;}
function groupedCards(){const rows=filteredProjects();if(!rows.length)return empty('Chưa tìm thấy workspace','Thử tên khác hoặc bỏ bộ lọc ghim.');return [{group:'research',title:'Dự án & nghiên cứu',copy:'Theo dõi mốc công việc và điều kiện còn mở.'},{group:'tools',title:'Công cụ thị trường',copy:'Tra cứu snapshot và khám phá bộ lọc. Giữ rõ loại dữ liệu.'}].map(g=>{const items=rows.filter(p=>(p.group||'research')===g.group);return items.length?`<section class="workspace-group" data-group="${g.group}"><div class="section-heading"><div><h2>${g.title}<small>${items.length}</small></h2><p>${g.copy}</p></div></div><div class="project-grid">${items.map(card).join('')}</div></section>`:'';}).join('');}
function toolsPage(){return `<div class="notice">Ba công cụ giữ rõ nguồn riêng: Stock Monitor là snapshot; LunaVN là minh hoạ; Fundamental Panel có các mục dữ liệu còn thiếu. Kết nối không xác nhận dữ liệu thị trường thực.</div><div class="project-grid">${portfolio.projects.filter(p=>p.group==='tools').map(card).join('')}</div>`;}
function filteredProjects(){return portfolio.projects.filter(p=>(!onlyPinned||pins.includes(p.id))&&(!projectFilter||(p.name+' '+p.category+' '+p.phase+' '+p.description).toLowerCase().includes(projectFilter.toLowerCase())));}
function empty(title,detail){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;}
function projectsPage(){return `<div class="toolbar"><input class="field-input" id="project-search" placeholder="Tìm dự án hoặc phạm vi…" aria-label="Tìm dự án trong danh sách" value="${esc(projectFilter)}"><div class="tabs"><button data-pins-filter="all" class="${!onlyPinned?'selected':''}">Tất cả dự án</button><button data-pins-filter="pinned" class="${onlyPinned?'selected':''}">Đã ghim</button></div></div>${foundationFeature()}${groupedCards()}`;}
function milestoneRows(rows){return rows.map(m=>{const p=project(m.project_id);return `<tr><td><a class="project-inline ${p.color}" href="#project/${p.id}"><i class="project-dot"></i>${esc(p.name)}</a></td><td><strong>${esc(m.id)} · ${esc(m.title)}</strong><small>${esc(m.detail)}</small></td><td>${badge(m.label||stateLabels[m.state]||m.state,milestoneTone(m.state))}<div class="state-literal">${esc(m.state)}</div></td><td><small>${esc(m.scope||'Theo nguồn dự án')}</small></td></tr>`;}).join('');}
function milestonesPage(){const all=portfolio.projects.flatMap(p=>p.milestones);const rows=all.filter(m=>(milestoneProject==='all'||m.project_id===milestoneProject)&&(milestoneState==='all'||(milestoneState==='attention'?/BLOCK|PENDING|FAILED/.test(m.state):/ACCEPT|SCOPED|APPLIED/.test(m.state))));return `<div class="notice">Mỗi mốc giữ nguyên trạng thái và phạm vi của dự án gốc. <strong>Không cộng thành phần trăm hoàn thành chung.</strong> Kronos hiện chỉ cung cấp readiness kỹ thuật trong phạm vi kết nối.</div><div class="toolbar"><select id="milestone-project" class="field-input" aria-label="Lọc mốc theo dự án"><option value="all">Tất cả dự án</option>${portfolio.projects.map(p=>`<option value="${p.id}" ${milestoneProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="milestone-state" class="field-input" aria-label="Lọc loại trạng thái"><option value="all">Mọi trạng thái</option><option value="attention" ${milestoneState==='attention'?'selected':''}>Chờ xử lý / bị chặn</option><option value="scoped" ${milestoneState==='scoped'?'selected':''}>Đã áp dụng / nhận trong scope</option></select><span class="muted">${rows.length} / ${all.length} mốc</span></div><section class="paper-panel table-panel"><div class="table-scroll"><table><thead><tr><th>Dự án</th><th>Mốc và phạm vi</th><th>Trạng thái ghi nhận</th><th>Ngữ cảnh</th></tr></thead><tbody>${milestoneRows(rows)}</tbody></table></div>${rows.length?'':empty('Chưa có mốc trong bộ lọc','Chọn dự án hoặc trạng thái khác.')}</section>`;}
function attentionPage(){return `<div class="section-heading"><div><h2>Bước tiếp theo đã có nguồn</h2><p>Trang này theo dõi điều kiện còn mở, không cấp quyền thực thi.</p></div></div><section class="paper-panel">${attentionItems()}</section>`;}
function sourcesPage(){return `<div class="notice"><strong>${local?'Đang đọc trực tiếp metadata local.':'Đang xem snapshot công khai.'}</strong> Kết nối thành công chỉ xác nhận nguồn phản hồi. Hash response giúp đối chiếu lần đọc; không thay phê chuẩn hoặc kiểm chứng khoa học.</div><div class="source-grid">${portfolio.projects.map(p=>`<section class="paper-panel source-card ${p.color}"><h3 class="project-inline"><span class="project-dot"></span>${esc(p.name)}</h3><dl><dt>Nguồn</dt><dd>Dashboard ${p.port} · ${esc(p.endpoint)}</dd><dt>Đọc lúc</dt><dd>${date(p.checked_at)}</dd><dt>Chế độ</dt><dd>${local?'Read-only local':'Snapshot đã xuất bản'}</dd><dt>Hash response</dt><dd class="hash">${esc(p.response_sha256||'Chưa đọc được response')}</dd><dt>Bản công khai</dt><dd>${p.public_url?`<a class="text-link" href="${esc(p.public_url)}" target="_blank" rel="noopener noreferrer">Đã có đường dẫn${icon('external')}</a>`:'Chưa đăng ký URL'}</dd></dl>${badge(p.connected?(p.stale?'Cần kiểm lại nguồn':'Nguồn phản hồi'):'Không kết nối được',p.connected&&!p.stale?'teal':'amber')}</section>`).join('')}</div>`;}
function detailPage(id){const p=project(id);if(!p)return empty('Không tìm thấy dự án','Chọn workspace đã đăng ký trong thanh bên.');return `<a href="#projects" class="text-link">${icon('back')}Tất cả dự án</a><section class="detail-banner ${p.color}">${projectMark(p)}<div><h2>${esc(p.name)} ${esc(p.suffix)}</h2><p>${esc(p.description)}</p></div><div class="detail-actions">${externalButton(p,'Mở dashboard gốc')}${p.public_url&&local?`<a class="button ghost" href="${esc(p.public_url)}" target="_blank" rel="noopener noreferrer">Bản trên Internet${icon('external')}</a>`:''}</div></section>${missionPanel(id)}<div class="detail-summary"><section class="paper-panel"><h3>Mốc hiện tại</h3><strong>${esc(p.phase)}</strong><p>${esc(p.phase_title)}</p></section><section class="paper-panel"><h3>Trạng thái theo nguồn</h3>${badge(p.status_label,p.status_tone)}<p>${esc(p.status_literal)}</p></section><section class="paper-panel"><h3>Việc tiếp theo</h3><strong class="next-step-title">${esc(p.next_action)}</strong></section></div><section class="paper-panel"><div class="section-heading"><div><h2>${p.group==='tools'?'Thông tin công cụ':'Mốc công việc'}</h2><p>Theo đúng phạm vi của ${esc(p.name)}.</p></div><span class="muted">${p.milestones.length} mốc</span></div>${p.milestones.length?`<div class="table-scroll"><table><thead><tr><th>Dự án</th><th>Mốc và phạm vi</th><th>Trạng thái</th><th>Ngữ cảnh</th></tr></thead><tbody>${milestoneRows(p.milestones)}</tbody></table></div>`:(p.group==='tools'?`<div class="card-facts">${p.facts.map(f=>`<div><span>${esc(f.label)}</span><strong>${esc(f.value)}</strong></div>`).join('')}</div><p class="muted">${esc(p.phase_basis)}</p>`:empty('Chưa có milestone API',p.phase_basis||'Khôi phục kết nối metadata để đọc trạng thái hiện tại.'))}<div class="doc-links">${p.documents.map(d=>externalButton(p,d.title,d.route)).join('')}</div></section><section class="paper-panel detail-attention"><div class="section-heading"><h2>Điều cần giữ rõ</h2></div>${p.attention.map(a=>`<div class="attention-item ${p.color}"><span class="attention-marker">${icon('circle')}</span><div class="attention-copy"><h3>${esc(a.title)}</h3><p>${esc(a.detail)}</p></div></div>`).join('')}</section>`;}
function render(){if(!portfolio)return;let [route,id]=location.hash.slice(1).split('/');if(!(route in titles)&&route!=='project'&&route!=='mission')route='overview';$('#page-title').textContent=route==='mission'?('Mission · '+(project(id)?.name||'Module')):route==='project'?(project(id)?.name||'Workspace'):titles[route];$('#crumb').textContent=$('#page-title').textContent;$('#greeting').textContent=route==='overview'?'Bàn làm việc của bạn':route==='project'?'Workspace dự án':'Toàn bộ không gian nghiên cứu';document.title=$('#page-title').textContent+' · FiTechHub';document.querySelectorAll('[data-nav]').forEach(a=>{let active=a.dataset.nav===(route==='mission'||route==='connections'?'missions':route==='project'?(project(id)?.group==='foundation'?'foundation':project(id)?.group==='tools'?'tools':'projects'):route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const renderer={live:()=>FiTechLive.shell(local),overview,projects:projectsPage,milestones:milestonesPage,attention:attentionPage,sources:sourcesPage,tools:toolsPage,missions:missionsPage,connections:()=>connectionsPage(id),mission:()=>missionPage(id),project:()=>detailPage(id)}[route];$('#content').innerHTML=renderer();wireFilters();if(route==='live')FiTechLive.mount(portfolio.projects);}
function wireFilters(){const ps=$('#project-search');if(ps)ps.addEventListener('input',()=>{const pos=ps.selectionStart;projectFilter=ps.value;render();$('#project-search').focus();$('#project-search').setSelectionRange(pos,pos);});$('#milestone-project')?.addEventListener('change',e=>{milestoneProject=e.target.value;render();});$('#milestone-state')?.addEventListener('change',e=>{milestoneState=e.target.value;render();});}
async function refresh(manual=false){if(busy)return;busy=true;$('#refresh').disabled=true;try{const [response,missionResponse]=await Promise.all([fetch(local?'./api/portfolio':'./data/portfolio.json',{cache:'no-store'}),fetch('./data/missions.json',{cache:'no-store'})]);if(!missionResponse.ok)throw new Error('Chưa đọc được mission registry');missionRegistry=validateMissionRegistry(await missionResponse.json());if(!response.ok)throw new Error('Nguồn trả về '+response.status);const next=await response.json();if(next.schema!=='FITECHHUB_PORTFOLIO_V1'||![4,6,7,8].includes(next.projects.length)||next.total!==next.projects.length||next.authority_supported!==false)throw new Error('Schema chưa được đăng ký');portfolio=next;document.querySelector('.nav-count').textContent=next.projects.filter(p=>(p.group||'research')==='research').length;document.querySelector('.nav-count-tools').textContent=next.projects.filter(p=>p.group==='tools').length;$('#connection').innerHTML=`<i></i>${local?next.connected+'/'+next.total+' nguồn đang phản hồi':'Bản chia sẻ công khai'}`;$('#connection').classList.toggle('warning',next.connected!==next.total);$('#freshness').textContent=(local?'Đọc nguồn lúc ':'Snapshot lúc ')+date(next.observed_at);$('#error-banner').hidden=true;if(manual||(!['INPUT','SELECT'].includes(document.activeElement.tagName)&&!$('#search-dialog').open))render();}catch(e){$('#error-banner').hidden=false;$('#error-banner').textContent='Chưa làm mới được dữ liệu. '+e.message+(portfolio?' Đang giữ lần quan sát trước đó.':' Kiểm tra dịch vụ tổng hợp và thử lại.');$('#connection').innerHTML='<i></i>Chưa xác nhận kết nối';$('#connection').classList.add('warning');}finally{busy=false;$('#refresh').disabled=false;}}
function searchResults(){const q=$('#command-input').value.toLowerCase();const rows=portfolio?.projects.filter(p=>(p.name+' '+p.category+' '+p.phase+' '+p.description).toLowerCase().includes(q))||[];$('#search-results').innerHTML=rows.length?rows.map(p=>`<a class="search-result ${p.color}" href="#project/${p.id}" data-search-result>${projectMark(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.phase)} · ${esc(p.category)}</small></span></a>`).join(''):empty('Chưa tìm thấy dự án','Thử một từ khóa khác.');}
function openSearch(){searchResults();$('#search-dialog').showModal();$('#command-input').focus();}
document.addEventListener('click',e=>{const pin=e.target.closest('[data-pin]');if(pin){pins=pins.includes(pin.dataset.pin)?pins.filter(x=>x!==pin.dataset.pin):[...pins,pin.dataset.pin];try{localStorage.setItem('fitechhub-pins',JSON.stringify(pins));}catch{}render();}const filter=e.target.closest('[data-pins-filter]');if(filter){onlyPinned=filter.dataset.pinsFilter==='pinned';render();}if(e.target.closest('[data-search-result]'))$('#search-dialog').close();});
$('#search-open').addEventListener('click',openSearch);$('#close-search').addEventListener('click',()=>$('#search-dialog').close());$('#command-input').addEventListener('input',searchResults);document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();openSearch();}});$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
let theme='light';try{theme=localStorage.getItem('fitechhub-theme')||'light';}catch{}function applyTheme(){document.documentElement.dataset.theme=theme;$('#theme-toggle').setAttribute('aria-pressed',String(theme==='dark'));}applyTheme();$('#theme-toggle').addEventListener('click',()=>{theme=theme==='light'?'dark':'light';try{localStorage.setItem('fitechhub-theme',theme);}catch{}applyTheme();});$('#refresh').addEventListener('click',()=>refresh(true));window.addEventListener('hashchange',render);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});refresh();setInterval(()=>{if(!document.hidden)refresh();},30000);
